INSERT INTO courses(title,slug,summary,description,level,duration,published)
VALUES
('Farm Business Foundations','farm-business-foundations','Learn the basics of enterprise selection, farm budgeting, record keeping and practical business decisions.','A short introductory course for new and growing farm businesses. It covers how to define a production goal, list the resources required, estimate costs, keep records and review business performance. Adapt every budget to local prices and actual farm conditions.','beginner','3 lessons · 45 minutes',true),
('Crop Production Planning','crop-production-planning','Build a crop production plan around your location, season, resources and market.','An introductory course on production calendars, field observation, input planning and harvest preparation. Local extension recommendations and crop-specific guidance should be used when developing a real production plan.','beginner','3 lessons · 50 minutes',true),
('Soil Health Essentials','soil-health-essentials','Understand soil sampling, soil test interpretation, fertility planning and conservation.','A practical introduction to soil health and responsible nutrient management. Soil decisions should be based on representative samples, laboratory results and the needs of the crop and location.','beginner','3 lessons · 45 minutes',true)
ON CONFLICT(slug) DO NOTHING;
INSERT INTO lessons(course_id,title,content,position)
SELECT c.id,v.title,v.content,v.position FROM courses c
JOIN (VALUES
('farm-business-foundations','Set a clear farm enterprise goal','Start with a clear production and market goal. Identify the product, expected buyers, production calendar and the scale you can manage. List land, water, labour, equipment, inputs, transport, storage and working capital. Separate assumptions from confirmed information and revisit assumptions before committing significant funds.',1),
('farm-business-foundations','Prepare a simple farm budget','Create a cost list for land preparation, seed or stock, fertiliser and other inputs, labour, water, equipment, transport, storage and administration. Distinguish one-time setup costs from recurring production costs. Use current local quotations, record the source and date, and prepare a contingency rather than relying on optimistic estimates.',2),
('farm-business-foundations','Keep records and review performance','Record dates, quantities, purchases, labour, field activities, harvest volumes, sales and losses. Review records at the end of each production cycle. Compare actual costs and output with the plan, identify the main differences and use the evidence to improve the next cycle.',3),
('crop-production-planning','Match crop choice to the farm context','Consider local climate, soil characteristics, water availability, growing season, labour, input access, storage and market demand. Speak with local extension officers and buyers before finalising crop choice. Avoid choosing a crop based only on a high advertised selling price.',1),
('crop-production-planning','Build a field activity calendar','Map the production cycle from land preparation through planting, crop monitoring, irrigation, weeding, nutrient management, harvest and post-harvest handling. Assign responsibilities and dates, but leave room for weather and field conditions. Record what actually happens so the calendar improves over time.',2),
('crop-production-planning','Monitor fields and prepare for harvest','Walk fields regularly and record crop growth, plant population, water conditions, visible stress and unusual symptoms. Compare observations across areas of the field. Plan harvest labour, containers, handling, storage and transport before the expected harvest window.',3),
('soil-health-essentials','Collect representative soil samples','Divide the farm into areas with similar soil and management history. Avoid unusual spots such as manure heaps, field edges and recently fertilised patches. Follow the laboratory sampling instructions for depth, sample number, labelling and packaging. A representative sample is more useful than a convenient but biased sample.',1),
('soil-health-essentials','Read a soil test with context','Review pH, organic matter and reported nutrient values alongside the crop, sampling depth, laboratory method and local interpretation guide. Do not apply fertiliser solely from a generic online table. Ask a qualified agronomist or extension professional to interpret results for the crop and location.',2),
('soil-health-essentials','Protect soil structure and fertility','Maintain soil cover where appropriate, manage erosion, avoid unnecessary compaction, return suitable organic residues and plan rotations around local crop systems. Monitor drainage and water movement. Sustainable soil management is a continuing process, not a one-time input purchase.',3)
) AS v(course_slug,title,content,position) ON c.slug=v.course_slug
WHERE NOT EXISTS (SELECT 1 FROM lessons l WHERE l.course_id=c.id AND l.position=v.position);
